// quickRouteByPrefix 便于分发时按 prefix 精确查找（served 段用形状匹配，这里只做校验）。
func quickRouteByPrefix(prefix string) (quickRoute, bool) {
	for _, r := range quickRoutes {
		if r.Prefix == prefix {
			return r, true
		}
	}
	return quickRoute{}, false
}
